-- Aplicar después de cada dbt build: dbt recrea los marts.
-- PK/FK físicas complementan las pruebas dbt.
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='marts.dim_fecha'::regclass AND conname='dim_fecha_pkey') THEN ALTER TABLE marts.dim_fecha ADD CONSTRAINT dim_fecha_pkey PRIMARY KEY (fecha_key); END IF; END $$;
