DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='marts.bridge_promocion_venta'::regclass AND conname='bridge_promocion_venta_venta_key_fkey') THEN ALTER TABLE marts.bridge_promocion_venta ADD CONSTRAINT bridge_promocion_venta_venta_key_fkey FOREIGN KEY (venta_key) REFERENCES marts.fact_ventas (venta_key); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='marts.bridge_promocion_venta'::regclass AND conname='bridge_promocion_venta_promocion_key_fkey') THEN ALTER TABLE marts.bridge_promocion_venta ADD CONSTRAINT bridge_promocion_venta_promocion_key_fkey FOREIGN KEY (promocion_key) REFERENCES marts.dim_promocion (promocion_key); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='marts.fact_ventas'::regclass AND conname='fact_ventas_range_check') THEN ALTER TABLE marts.fact_ventas ADD CONSTRAINT fact_ventas_range_check CHECK (cantidad > 0 AND precio_unitario >= 0 AND descuento BETWEEN 0 AND 1); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='marts.fact_inventario'::regclass AND conname='fact_inventario_range_check') THEN ALTER TABLE marts.fact_inventario ADD CONSTRAINT fact_inventario_range_check CHECK (stock_disponible >= 0 AND stock_minimo >= 0 AND stock_maximo >= stock_minimo); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='marts.fact_metas'::regclass AND conname='fact_metas_range_check') THEN ALTER TABLE marts.fact_metas ADD CONSTRAINT fact_metas_range_check CHECK (meta_ventas > 0 AND meta_unidades > 0); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='marts.fact_proveedor_precio'::regclass AND conname='fact_proveedor_precio_range_check') THEN ALTER TABLE marts.fact_proveedor_precio ADD CONSTRAINT fact_proveedor_precio_range_check CHECK (costo_proveedor >= 0 AND plazo_dias > 0); END IF; END $$;
